64: export function classifyWorkerTransportFailure(
65:   observation: WorkerTransportFailureObservation,
66: ): WorkerTransportFailureClass | null {
67:   if (observation.nativeResultDisposition !== undefined) {
68:     // Preserve process/safety facts. Only the actual exact raw-contract owner
69:     // can make a complete artifact available despite a later ordinary exit.
70:     if (observation.lane === "closed_prompt_proof" && observation.toolCallCount > 0) return "contract_failure";
71:     if (observation.nativeResultDisposition === "admitted" && observation.terminationConfirmed &&
72:         !observation.processSpawnFailed && !observation.timedOut) return null;
73:     if (observation.nativeResultDisposition === "rejected") return "contract_failure";
74:   }
75:   if (
76:     observation.timedOut || !observation.terminationConfirmed ||
77:     observation.processSpawnFailed || observation.processStatus !== 0 ||
78:     observation.apiRetryCount > 0 ||
79:     (observation.parser === "claude_stream_json" &&
80:       observation.structuredEventCount === 0)
81:   ) return "transport_failure";
82:   if (
83:     observation.lane === "closed_prompt_proof" &&
84:     observation.toolCallCount > 0
85:   ) return "contract_failure";
86:   return observation.finalOutput.trim().length === 0 ? "no_output" : null;
87: }
